def execute(inputs, parameters):
    # Transform data based on operation
    operation = parameters.get('operation', 'merge')

    if operation == 'merge':
        result = {}
        for item in inputs.values():
            if isinstance(item, dict):
                result.update(item)
        return result

    return inputs

